/* ===== Numeria Quest — Katalog Equipment (125 item + 15 material drop monster) =====
   Dimuat PALING AKHIR (setelah npc_apply.js). Tidak mengubah file lain: EQ ditambah, fungsi game dibungkus.
   Isi:
   - 125 equipment dari gambar katalog: Pedang / Busur / Tongkat Sihir (slot Senjata), Armor (Badan), Jubah (Jubah),
     5 tingkat: Common, Uncommon, Rare, Epic, Legendary. Tiap item punya stat penguat + efek khusus sesuai namanya.
   - Senjata hanya bisa dipakai job yang cocok: Pedang = Pendekar Pedang, Busur = Pemanah, Tongkat Sihir = Penyihir.
   - Bonus Set: 2-3 bagian (senjata/armor/jubah) dengan tema nama yang sama (mis. Naga, Void, Phoenix) memberi bonus tambahan.
   - Penguatan +1..+5 di Pandai Besi (NPC bernama/berperan "pandai" di kota mana pun), memakai material drop monster + koin.
   - Monster menjatuhkan material (sesuai jenis monster) dan kadang equipment (lebih bagus dari monster yang lebih kuat).
   - Efek: Curi HP, Bakar, Beku, Sengat, Hindar, Regen HP/Mana, Redam, Pantul, Bonus Koin/XP/Drop, Energi Ulti.
   Konsol: EQX.give("pd2_0") memberi item, EQX.mat(8, 5) memberi 5 Kristal Es, EQX.all untuk daftar kunci. */
(() => {
  if (typeof EQ === "undefined" || typeof Pl === "undefined" || typeof inv !== "function" || typeof win !== "function" || typeof bon !== "function") {
    console.warn("[equip_katalog] dilewati: EQ / Pl / inv / win / bon tidak ditemukan");
    return;
  }
  const NAMES = {"pd": [["Pedang Besi", "Pedang Kayu", "Pedang Prajurit", "Pedang Pemburu", "Pedang Rusak"], ["Pedang Elang", "Pedang Naga Kecil", "Pedang Ksatria", "Pedang Bayangan", "Pedang Raksasa"], ["Pedang Pahlawan", "Pedang Salju", "Pedang Langit", "Pedang Kristal", "Pedang Cahaya"], ["Pedang Raja Iblis", "Pedang Lava", "Pedang Jiwa", "Pedang Abadi", "Pedang Void"], ["Pedang Tuan Naga", "Pedang Benedikta", "Pedang Surga", "Pedang Kiamat", "Pedang Cosmos"]], "bs": [["Busur Kayu", "Busur Kecil", "Busur Pemburu", "Busur Baja", "Busur Rusak"], ["Busur Elang", "Busur Hijau", "Busur Siluman", "Busur Kavaleri", "Busur Raksasa"], ["Busur Es", "Busur Petir", "Busur Langit", "Busur Kristal", "Busur Bayangan"], ["Busur Naga", "Busur Iblis", "Busur Jiwa", "Busur Void", "Busur Phoenix"], ["Busur Surga", "Busur Cosmos", "Busur Takdir", "Busur Kiamat", "Busur Astral"]], "tk": [["Tongkat Kayu", "Tongkat Kecil", "Tongkat Penyembuh", "Tongkat Batu", "Tongkat Retak"], ["Tongkat Es", "Tongkat Angin", "Tongkat Alam", "Tongkat Api", "Tongkat Bayangan"], ["Tongkat Kristal", "Tongkat Petir", "Tongkat Bintang", "Tongkat Bulan", "Tongkat Naga"], ["Tongkat Iblis", "Tongkat Kegelapan", "Tongkat Jiwa", "Tongkat Waktu", "Tongkat Void"], ["Tongkat Surga", "Tongkat Cosmos", "Tongkat Takdir", "Tongkat Kiamat", "Tongkat Elemen"]], "ar": [["Baju Besi Kain", "Baju Kulit", "Baju Prajurit", "Rantai Besi", "Baju Robek"], ["Baju Pemburu", "Baju Elang", "Baju Ksatria", "Baju Siluman", "Baju Naga Kecil"], ["Baju Pahlawan", "Baju Salju", "Baju Langit", "Baju Kristal", "Baju Bayangan"], ["Baju Raja Iblis", "Baju Lava", "Baju Jiwa", "Baju Void", "Baju Phoenix"], ["Baju Surga", "Baju Cosmos", "Baju Takdir", "Baju Kiamat", "Baju Naga"]], "jb": [["Jubah Kain", "Jubah Pendek", "Jubah Prajurit", "Jubah Robek", "Jubah Hitam"], ["Jubah Hijau", "Jubah Biru", "Jubah Merah", "Jubah Elang", "Jubah Bayangan"], ["Jubah Kristal", "Jubah Langit", "Jubah Petir", "Jubah Naga", "Jubah Bulan"], ["Jubah Iblis", "Jubah Kegelapan", "Jubah Jiwa", "Jubah Void", "Jubah Phoenix"], ["Jubah Surga", "Jubah Cosmos", "Jubah Takdir", "Jubah Kiamat", "Jubah Naga Emas"]]},
    MATN = ["Taring Serigala", "Cakar Goblin", "Tanduk Minotaur", "Sisik Naga", "Garis Iblis", "Bulu Harpy", "Racun Spider", "Cangkang Kura-kura", "Kristal Es", "Tulang Undead", "Mata Gorgon", "Bulu Phoenix", "Tanduk Leviathan", "Inti Elemental", "Tinta Kraken"],
    ATLAS = "data:image/png;base64,";
  const CATS = [
      { k: "pd", n: "Pedang", s: "w", wt: "sword", ci: 0 },
      { k: "bs", n: "Busur", s: "w", wt: "archer", ci: 1 },
      { k: "tk", n: "Tongkat Sihir", s: "w", wt: "mage", ci: 2 },
      { k: "ar", n: "Armor", s: "b", ci: 3 },
      { k: "jb", n: "Jubah", s: "c", ci: 4 },
    ],
    RAR = [
      { n: "Common", c: "#b8c0cc" },
      { n: "Uncommon", c: "#5be08a" },
      { n: "Rare", c: "#4db8ff" },
      { n: "Epic", c: "#b070ff" },
      { n: "Legendary", c: "#ffc233" },
    ],
    JOBN = { sword: "Pendekar Pedang", archer: "Pemanah", mage: "Penyihir" },
    WTN = { sword: "Pedang", archer: "Busur", mage: "Tongkat Sihir" };
  /* stat dasar per kategori & tingkat */
  const BASE = {
    pd: { atk: [4, 8, 13, 20, 30], crit: [0, 1, 2, 3, 5] },
    bs: { atk: [3, 7, 11, 17, 26], crit: [3, 5, 8, 11, 15] },
    tk: { atk: [3, 6, 10, 15, 23], mp: [10, 18, 28, 42, 60] },
    ar: { def: [2, 4, 7, 11, 16], hp: [10, 20, 35, 55, 80] },
    jb: { def: [1, 2, 3, 5, 8], mp: [6, 12, 20, 30, 44], hp: [0, 6, 12, 20, 30] },
  };
  const VAR = [1, 1, 1.03, 1.06, 1.1],
    TM = [1, 1.5, 2.2, 3, 4]; /* pengali efek per tingkat */
  /* efek khusus menurut kata di nama item (maks 2 per item). nilai = dasar x TM[tingkat] */
  const PERKS = [
    [/Phoenix/, { burn: 8, reg: 2 }],
    [/Lava|Api/, { burn: 12 }],
    [/Raja Iblis|Iblis/, { ls: 2, atk: 1 }],
    [/Salju|\bEs\b|Kristal/, { frz: 8 }],
    [/Petir/, { shk: 7 }],
    [/Jiwa/, { ls: 2.5 }],
    [/Bayangan|Siluman|Hitam/, { dod: 4 }],
    [/Elang|Langit/, { crit: 2 }],
    [/Naga/, { pen: 2, atk: 1 }],
    [/Cahaya|Surga|Benedikta|Penyembuh|Hijau|Alam/, { reg: 2 }],
    [/Void|Kiamat/, { pen: 3 }],
    [/Cosmos|Takdir|Abadi|Astral|Bintang/, { ult: 10 }],
    [/Waktu|Bulan/, { mreg: 3 }],
    [/Pemburu/, { drop: 6 }],
    [/Prajurit|Ksatria|Pahlawan/, { blk: 2 }],
    [/Baja|Rantai|Raksasa/, { ref: 3 }],
    [/Elemen/, { burn: 5, frz: 5, shk: 5 }],
  ];
  const LBL = {
      atk: ["Serangan", ""], def: ["Pertahanan", ""], hp: ["HP", ""], mp: ["Mana", ""], crit: ["Critical", "%"], pen: ["Penetrasi", "%"],
      ls: ["Curi HP", "%"], burn: ["Peluang Bakar", "%"], frz: ["Peluang Beku", "%"], shk: ["Peluang Sengat", "%"], dod: ["Hindar", "%"],
      reg: ["Regen HP/giliran", ""], mreg: ["Regen Mana/giliran", ""], blk: ["Redam damage", "%"], ref: ["Pantul damage", "%"],
      coinP: ["Bonus Koin", "%"], xpP: ["Bonus XP", "%"], drop: ["Bonus Drop", "%"], ult: ["Energi Ulti", "%"],
    },
    PLAIN = ["atk", "def", "hp", "mp", "crit", "pen"],
    ORDER = Object.keys(LBL);
  const FXD = {
    burn: "Serangan terakhir bisa membakar musuh 2 giliran",
    frz: "Serangan terakhir bisa membekukan musuh (damage musuh turun)",
    shk: "Serangan terakhir bisa menyengat musuh (musuh lewat 1 giliran)",
    ls: "Sebagian damage yang kamu beri kembali jadi HP",
    dod: "Kadang serangan musuh luput sepenuhnya",
    blk: "Mengurangi damage yang kamu terima",
    ref: "Memantulkan sebagian damage ke musuh",
  };
  /* ---------- bangun item ---------- */
  const ITEMS = {},
    BASEST = {},
    ALL = [];
  CATS.forEach((c, ci) =>
    NAMES[c.k].forEach((row, t) =>
      row.forEach((nm, si) => {
        const key = c.k + t + "_" + si,
          bad = /Rusak|Robek|Retak/.test(nm),
          mul = bad ? 0.7 : VAR[si],
          st = {};
        Object.entries(BASE[c.k]).forEach(([s, a]) => {
          const v = Math.round(a[t] * mul);
          if (v > 0) st[s] = v;
        });
        let n = 0;
        for (const [re, fx] of PERKS) {
          if (n >= 2) break;
          if (!re.test(nm)) continue;
          n++;
          for (const [s, b] of Object.entries(fx)) st[s] = (st[s] || 0) + Math.max(1, Math.round(b * TM[t]));
        }
        const e = { n: nm, s: c.s, ...st };
        if (c.wt) e.wt = c.wt;
        if (c.s === "w") e.fist = e.sw = RAR[t].c;
        EQ[key] = e;
        BASEST[key] = { ...st };
        ITEMS[key] = { key, cat: c, t, si, ic: ci * 25 + t * 5 + si, nm };
        ALL.push(key);
      }),
    ),
  );
  const keyOf = (k) => ITEMS[k];
  /* harga toko (hanya Common & Uncommon pilihan) */
  const SHOP = { pd0_0: 90, bs0_2: 90, tk0_2: 90, ar0_2: 110, jb0_2: 70, pd1_2: 320, bs1_3: 320, tk1_2: 320, ar1_2: 380, jb1_2: 250 };
  Object.entries(SHOP).forEach(([k, p]) => (EQ[k].price = p));

  /* ---------- statistik: penguatan & bonus set ---------- */
  const up = () => (Pl.up = Pl.up || {}),
    mats = () => (Pl.mats = Pl.mats || {}),
    lvlOf = (k) => (Pl.up && Pl.up[k]) || 0,
    jobKey = () => (typeof job === "function" ? job() : Pl.job);
  function recompute(k) {
    const b = BASEST[k],
      e = EQ[k],
      l = lvlOf(k);
    for (const s in b) e[s] = l ? Math.max(Math.round(b[s] * (1 + 0.15 * l)), b[s] + l) : b[s];
  }
  const THEMES = ["Naga", "Void", "Phoenix", "Jiwa", "Kristal", "Langit", "Bayangan", "Iblis", "Surga", "Cosmos", "Kiamat", "Takdir", "Lava", "Salju", "Elang", "Pahlawan", "Prajurit", "Ksatria", "Pemburu", "Petir", "Bulan", "Raksasa", "Es"];
  EQ._set = { n: "Bonus Set", s: "x" };
  let setInfo = null;
  function refreshSet() {
    ALL.forEach((k) => recompute(k));
    const ps = ["w", "b", "c"].map((s) => Pl.eq && Pl.eq[s]).filter((k) => k && ITEMS[k]);
    let best = null;
    for (const th of THEMES) {
      const m = ps.filter((k) => new RegExp("\\b" + th + "\\b").test(ITEMS[k].nm));
      if (m.length >= 2 && (!best || m.length > best.n)) best = { th, n: m.length, t: m.reduce((a, k) => a + ITEMS[k].t, 0) / m.length };
    }
    ["atk", "def", "crit", "hp"].forEach((s) => delete EQ._set[s]);
    if (best) {
      const f = best.t + 1,
        big = best.n >= 3;
      EQ._set.atk = Math.round((big ? 5 : 2) * f);
      EQ._set.def = Math.round((big ? 5 : 2) * f);
      if (big) {
        EQ._set.crit = 3;
        EQ._set.hp = Math.round(10 * f);
      }
      setInfo = { th: best.th, n: best.n, atk: EQ._set.atk, def: EQ._set.def, crit: EQ._set.crit || 0, hp: EQ._set.hp || 0 };
    } else setInfo = null;
    if (Pl.eq) Pl.eq.x = best ? "_set" : null;
  }
  function refresh() {
    /* senjata yang tidak cocok dengan job dilepas */
    const w = Pl.eq && Pl.eq.w;
    if (w && EQ[w] && EQ[w].wt && EQ[w].wt !== jobKey()) Pl.eq.w = null;
    refreshSet();
    if (typeof applyEq === "function") _applyEq();
  }
  const _applyEq = typeof applyEq === "function" ? applyEq : () => {};
  if (typeof applyEq === "function") {
    applyEq = function () {
      refreshSet();
      return _applyEq.apply(this, arguments);
    };
  }

  /* ---------- teks stat & efek ---------- */
  const fmt = (e) =>
    ORDER.filter((s) => e[s])
      .map((s) => `+${e[s]}${LBL[s][1]} ${LBL[s][0]}`)
      .join(" · ");
  const fxLines = (e) => {
    const o = [];
    ORDER.filter((s) => e[s] && !PLAIN.includes(s)).forEach((s) => {
      if (FXD[s]) o.push(`${LBL[s][0]} ${e[s]}${LBL[s][1]}: ${FXD[s]}`);
    });
    return o;
  };

  /* ---------- efek dalam battle ---------- */
  let hpBefore = 0;
  const _hitNum = hitNum;
  hitNum = function (d, c, o) {
    const r = _hitNum.apply(this, arguments);
    try {
      if (typeof S === "undefined" || !S || !S.e || Pl.hp <= 0) return r;
      o = o || {};
      const ls = bon("ls");
      if (ls > 0 && d > 0) {
        const h = Math.max(1, Math.round((d * ls) / 100));
        Pl.hp = Math.min(mhp(), Pl.hp + h);
        flo("+" + h, "h", "#7ef0c8");
        bars();
      }
      if (o.last) {
        const roll = (k) => Math.random() * 100 < Math.min(75, bon(k));
        if (roll("burn")) {
          S.burn = { n: 2, d: Math.max(2, Math.round(pwr() * 0.3)) };
          flo("BAKAR", "e", "#ff7a3a");
        }
        if (roll("frz")) {
          S.freeze = 2;
          flo("BEKU", "e", "#7cf0ff");
        }
        if (roll("shk")) {
          S.stun = Math.max(S.stun || 0, 1);
          flo("SENGAT", "e", "#ffe14d");
        }
      }
    } catch (err) {}
    return r;
  };
  const _enemyTurn = enemyTurn;
  enemyTurn = function () {
    try {
      if (mode !== "w" && mode !== "x" && Pl.hp > 0) {
        const rg = bon("reg"),
          mr = bon("mreg");
        if (rg || mr) {
          Pl.hp = Math.min(mhp(), Pl.hp + rg);
          Pl.fp = Math.min(mmp(), Pl.fp + mr);
          if (rg) flo("+" + rg, "h", "#7ef0c8");
          bars();
        }
      }
      hpBefore = Pl.hp;
    } catch (err) {}
    return _enemyTurn.apply(this, arguments);
  };
  const _flo = flo;
  flo = function (t, w, c) {
    try {
      if (w === "h" && typeof t === "string" && /^-\d+$/.test(t) && typeof S !== "undefined" && S && S.e && mode !== "x" && mode !== "w") {
        const per = +t.slice(1),
          dod = Math.min(60, bon("dod"));
        if (dod > 0 && Math.random() * 100 < dod) {
          Pl.hp = Math.min(mhp(), Math.max(Pl.hp, hpBefore));
          bars();
          return _flo.call(this, "HINDAR!", "h", "#7cf0ff");
        }
        const blk = Math.min(60, bon("blk"));
        if (blk > 0) {
          const back = Math.round((per * blk) / 100);
          if (back > 0) {
            Pl.hp = Math.min(mhp(), Pl.hp + back);
            t = "-" + (per - back);
          }
        }
        const ref = bon("ref");
        if (ref > 0 && S.ehp > 0) {
          const rd = Math.max(1, Math.round((per * ref) / 100));
          S.ehp -= rd;
          setTimeout(() => _flo("PANTUL -" + rd, "e", "#ffb347"), 0);
          if (S.ehp <= 0) setTimeout(win, 700);
        }
        bars();
        hpBefore = Pl.hp;
      }
    } catch (err) {}
    return _flo.call(this, t, w, c);
  };
  const _gainUlt = gainUlt;
  gainUlt = function (n) {
    const u = bon("ult");
    return _gainUlt.call(this, u ? Math.round(n * (1 + u / 100)) : n);
  };

  /* ---------- drop monster ---------- */
  const MAT_RULES = [
    [/serigala|wolf/, 0], [/goblin|bandit/, 1], [/minotaur|banteng|bull|rhino|badak/, 2],
    [/naga|dragon|drak|kobra|snake|ular|kadal|lizard/, 3], [/iblis|demon|imp\b|devil|zodiak|ophiuchus|setan/, 4],
    [/harpy|owl|burung|bird|elang|gagak|bat\b|kelelawar/, 5], [/spider|laba|kalajengking|scorpion/, 6],
    [/kura|turtle|tortoise|crab|kepiting|siput|snail/, 7], [/\bes\b|ice|yeti|frost|salju|snow|beku/, 8],
    [/undead|mumi|mummy|skeleton|tulang|zombie|hantu|ghost|arwah/, 9], [/gorgon|medusa|basilisk/, 10],
    [/phoenix|fenix|fox|rubah|api\b|fire|lava|flame/, 11], [/leviathan|shark|hiu|whale|paus/, 12],
    [/kraken|jelly|ubur|octo|gurita|cumi|squid/, 14], [/elemental|golem|\bent\b|jamur|shroom|slime|crystal/, 13],
  ];
  const matFor = (e) => {
    const s = ((e.sp || "") + " " + (e.n || "")).toLowerCase();
    for (const [re, i] of MAT_RULES) if (re.test(s)) return i;
    return [0, 1, 13][(Math.random() * 3) | 0];
  };
  const tierOf = (e) => {
    const a = e.atk || 10;
    return a <= 10 ? 0 : a <= 16 ? 1 : a <= 22 ? 2 : a <= 28 ? 3 : 4;
  };
  const boss = (e) => (e.hp || 0) >= 400,
    elite = (e) => (e.hp || 0) >= 250;
  function rollDrops(e) {
    const out = { mats: [], eq: null, coin: 0, dup: false },
      dropB = 1 + bon("drop") / 100;
    /* material */
    if (boss(e) || Math.random() < Math.min(0.95, 0.6 * dropB)) {
      const i = matFor(e),
        n = boss(e) ? 2 + ((Math.random() * 2) | 0) : 1 + ((Math.random() * 2) | 0);
      mats()[i] = (mats()[i] || 0) + n;
      out.mats.push([i, n]);
      if (elite(e) && Math.random() < 0.3) {
        const j = (Math.random() * MATN.length) | 0;
        mats()[j] = (mats()[j] || 0) + 1;
        out.mats.push([j, 1]);
      }
    }
    /* equipment */
    const ch = boss(e) ? 1 : elite(e) ? 0.18 : 0.08;
    if (Math.random() < Math.min(1, ch * dropB)) {
      let t = tierOf(e);
      const r = Math.random();
      t = r < 0.6 ? t : r < 0.85 ? t - 1 : t + 1;
      if (boss(e)) t = Math.max(t, Math.min(4, tierOf(e) + 1));
      t = Math.max(0, Math.min(4, t));
      /* 50%: jenis senjata sesuai job pemain */
      const jk = jobKey(),
        cat = Math.random() < 0.5 ? CATS.find((c) => c.wt === jk) || CATS[0] : CATS[(Math.random() * CATS.length) | 0];
      const k = cat.k + t + "_" + ((Math.random() * 5) | 0);
      if (Pl.own[k]) {
        out.coin = 15 * (t + 1);
        Pl.coin += out.coin;
        out.dup = true;
      } else Pl.own[k] = 1;
      out.eq = k;
    }
    return out;
  }
  const _win = win;
  win = function () {
    const was = mode === "w",
      e = typeof S !== "undefined" && S ? S.e : null;
    _win.apply(this, arguments);
    if (was || !e) return;
    try {
      refresh();
      const cp = bon("coinP"),
        xp = bon("xpP");
      const bc = cp ? Math.round((e.coin * cp) / 100) : 0,
        bx = xp ? Math.round((e.xp * xp) / 100) : 0;
      Pl.coin += bc;
      Pl.xp += bx;
      const d = rollDrops(e);
      let h = "";
      if (bc || bx) h += `<div class="qm">Bonus equipment: ${bc ? "+" + bc + " koin " : ""}${bx ? "+" + bx + " XP" : ""}</div>`;
      d.mats.forEach(([i, n]) => (h += `<div class="dropx">${mic(i)} <b>${MATN[i]}</b> ×${n}</div>`));
      if (d.eq) {
        const it = ITEMS[d.eq];
        h += `<div class="dropx">${eic(it.ic)} <b style="color:${RAR[it.t].c}">${EQ[d.eq].n}</b> <small>(${RAR[it.t].n})</small>${d.dup ? ` <small>sudah punya → +${d.coin} koin</small>` : ' <span class="ok">item baru!</span>'}</div>`;
      }
      const card = document.querySelector("#ui .card");
      if (card && h) {
        const row = card.querySelector(".row"),
          div = document.createElement("div");
        div.className = "dropbox";
        div.innerHTML = h;
        row ? card.insertBefore(div, row) : card.appendChild(div);
      }
      if (typeof hud === "function") hud();
    } catch (err) {
      console.warn("[equip_katalog] drop gagal", err);
    }
  };

  /* ---------- tampilan ---------- */
  const css = document.createElement("style");
  css.textContent =
    `.eic,.mic{display:inline-block;flex:none;vertical-align:middle;background:url(${ATLAS}) no-repeat;background-size:640px 360px}` +
    ".eic{width:40px;height:40px}.mic{width:24px;height:24px;background-size:384px 216px}" +
    ".irow .ic.eicw{width:44px;font-size:0;text-align:center}" +
    ".dropbox{margin:6px 0;padding:4px 0;border-top:2px solid var(--line)}.dropx{display:flex;gap:6px;align-items:center;padding:2px 0}" +
    ".fxl{display:block;color:var(--mint);font-size:.9em}.rar{font-size:.85em}" +
    ".eqf{display:flex;flex-wrap:wrap;gap:4px;margin:4px 0}.eqf .b{padding:2px 8px;font-size:.85em}";
  document.head.appendChild(css);
  const eic = (i) => `<i class="eic" style="background-position:-${(i % 16) * 40}px -${((i / 16) | 0) * 40}px"></i>`,
    mic = (m) => {
      const i = 125 + m;
      return `<i class="mic" style="background-position:-${(i % 16) * 24}px -${((i / 16) | 0) * 24}px"></i>`;
    };
  let flt = "all";
  const FLT = [["all", "Semua"], ["w", "Senjata"], ["b", "Armor"], ["c", "Jubah"], ["h", "Topi"]];
  function decorate() {
    const tb = typeof tab !== "undefined" ? tab : 0;
    if (tb === 0) {
      const have = MATN.map((n, i) => [i, mats()[i] || 0]).filter((x) => x[1] > 0),
        ix = document.querySelector("#ix");
      if (ix && have.length) {
        const div = document.createElement("div");
        div.innerHTML =
          '<div class="qm" style="margin:6px 0 2px">Material monster (untuk Penguatan equipment)</div>' +
          have.map(([i, n]) => `<div class="irow"><span class="ic eicw">${mic(i)}</span><div><b>${MATN[i]} ×${n}</b></div></div>`).join("");
        ix.parentElement.parentElement.insertBefore(div, ix.parentElement);
      }
      return;
    }
    if (tb !== 1) return;
    const rows = [...document.querySelectorAll("#ui .irow")].filter((r) => r.querySelector("[data-e]"));
    if (!rows.length) return;
    if (setInfo) {
      const d = document.createElement("div");
      d.className = "qm";
      d.style.margin = "4px 0";
      d.innerHTML = `<span class="ok">Bonus Set ${setInfo.th} (${setInfo.n}/3):</span> +${setInfo.atk} Serangan, +${setInfo.def} Pertahanan${setInfo.crit ? ", +" + setInfo.crit + "% Critical" : ""}${setInfo.hp ? ", +" + setInfo.hp + " HP" : ""}`;
      rows[0].parentElement.insertBefore(d, rows[0]);
    }
    rows.forEach((r) => {
      const btn = r.querySelector("[data-e]"),
        k = btn.dataset.e,
        it = ITEMS[k];
      r.dataset.s = EQ[k].s;
      if (!it) return;
      const l = lvlOf(k),
        on = Pl.eq[EQ[k].s] === k;
      r.dataset.ord = (on ? 100 : 0) + it.t * 10 + (l ? 1 : 0);
      const ic = r.querySelector(".ic");
      if (ic) {
        ic.className = "ic eicw";
        ic.innerHTML = eic(it.ic);
      }
      const nm = r.querySelector("b"),
        sm = r.querySelector("small");
      if (nm) nm.style.color = RAR[it.t].c;
      if (nm) nm.textContent = EQ[k].n + (l ? " +" + l : "");
      if (sm) {
        const fl = fxLines(EQ[k]);
        sm.innerHTML = `<span class="rar" style="color:${RAR[it.t].c}">${RAR[it.t].n}</span> · ${it.cat.n}${it.cat.wt ? " · " + JOBN[it.cat.wt] : ""}<br>${fmt(EQ[k])}${fl.length ? '<span class="fxl">' + fl.join("<br>") + "</span>" : ""}`;
      }
      const o = btn.onclick;
      btn.onclick = (ev) => {
        const w = EQ[k];
        if (w.wt && w.wt !== jobKey() && Pl.eq.w !== k) {
          SND.sfx && SND.sfx("hurt");
          say(`${w.n} hanya bisa dipakai ${JOBN[w.wt]}. Job-mu sekarang ${JOBN[jobKey()] || jobKey()}.`);
          return;
        }
        return o.call(btn, ev);
      };
    });
    /* urutan: terpasang dulu, lalu tingkat tertinggi */
    const par = rows[0].parentElement,
      after = rows[rows.length - 1].nextSibling;
    rows.sort((x, y) => (+y.dataset.ord || 0) - (+x.dataset.ord || 0)).forEach((r) => par.insertBefore(r, after));
    /* filter jenis */
    const bar = document.createElement("div");
    bar.className = "eqf";
    bar.innerHTML = FLT.map(([k, n]) => `<button class="b ${flt === k ? "" : "g"}" data-f="${k}" type="button">${n}</button>`).join("");
    const apply = () => rows.forEach((r) => (r.style.display = flt === "all" || r.dataset.s === flt ? "" : "none"));
    bar.querySelectorAll("[data-f]").forEach(
      (b) =>
        (b.onclick = () => {
          flt = b.dataset.f;
          bar.querySelectorAll("[data-f]").forEach((x) => (x.className = "b " + (x.dataset.f === flt ? "" : "g")));
          apply();
        }),
    );
    const note = document.createElement("div");
    note.className = "qm";
    note.textContent = "Penguatan equipment dilakukan di Pandai Besi (ada di tiap kota).";
    par.insertBefore(note, par.querySelector(".irow") || null);
    par.insertBefore(bar, par.querySelector(".irow") || null);
    apply();
  }
  const _inv = inv;
  inv = function () {
    refresh();
    const r = _inv.apply(this, arguments);
    try {
      decorate();
    } catch (err) {
      console.warn("[equip_katalog] tampilan gagal", err);
    }
    return r;
  };

  /* ---------- penguatan ---------- */
  const AFF = [
    [/Phoenix|Lava|Api/, 11], [/Naga/, 3], [/Iblis/, 4], [/Salju|\bEs\b|Kristal/, 8], [/Petir|Elemen/, 13],
    [/Jiwa|Bayangan|Siluman|Hitam/, 9], [/Elang|Langit|Cahaya|Surga/, 5], [/Void|Kiamat/, 10], [/Cosmos|Takdir|Waktu|Astral|Abadi|Bintang/, 12],
    [/Bulan/, 14], [/Hijau|Alam/, 6], [/Pemburu|Kayu|Kain/, 0], [/Raksasa/, 2], [/Baja|Besi|Rantai|Prajurit|Ksatria|Pahlawan|Kulit/, 1],
  ];
  const affOf = (nm) => {
    for (const [re, i] of AFF) if (re.test(nm)) return i;
    return 13;
  };
  function openUp(k, back) {
    const it = ITEMS[k],
      e = EQ[k],
      l = lvlOf(k),
      m = affOf(it.nm),
      need = 2 * (l + 1),
      coin = 30 * (it.t + 1) * (l + 1),
      have = mats()[m] || 0,
      ok = l < 5 && have >= need && Pl.coin >= coin;
    const next = (() => {
      const o = {};
      for (const s in BASEST[k]) o[s] = Math.max(Math.round(BASEST[k][s] * (1 + 0.15 * (l + 1))), BASEST[k][s] + l + 1);
      return o;
    })();
    busy = true;
    ui(
      `<div class="card"><div class="ihd">${eic(it.ic)}<div><b style="color:${RAR[it.t].c}">${e.n}${l ? " +" + l : ""}</b> <small>(${RAR[it.t].n})</small><div class="qm">${fmt(e)}</div></div></div>` +
        (l >= 5
          ? '<div class="qm" style="margin:8px 0">Sudah mencapai penguatan maksimal (+5).</div>'
          : `<div class="qm" style="margin:8px 0">Penguatan +${l + 1}: ${fmt(next)}<br>Biaya: ${mic(m)} ${MATN[m]} ×${need} (punya ${have}) · ${coin} koin (punya ${Pl.coin})</div>`) +
        `<div class="row" style="margin-top:8px">${l < 5 ? `<button class="b" id="upgo" ${ok ? "" : "disabled"}>Perkuat</button>` : ""}<button class="b g" id="upbk">Kembali</button></div></div>`,
    );
    const go = document.querySelector("#upgo");
    if (go)
      go.onclick = () => {
        if (!ok) return;
        mats()[m] -= need;
        Pl.coin -= coin;
        up()[k] = l + 1;
        recompute(k);
        refresh();
        SND.sfx && SND.sfx("equip");
        if (typeof hud === "function") hud();
        say(`${e.n} diperkuat ke +${l + 1}!`);
        openUp(k, back);
      };
    document.querySelector("#upbk").onclick = () => (back ? back() : inv(1));
  }

  /* ---------- Pandai Besi: menu penguatan ---------- */
  let sf = "all";
  function smithMenu(who) {
    busy = true;
    refresh();
    const own = ALL.filter((k) => Pl.own[k] && (sf === "all" || EQ[k].s === sf)).sort(
        (a, b) => (Pl.eq[EQ[b].s] === b) - (Pl.eq[EQ[a].s] === a) || ITEMS[b].t - ITEMS[a].t || lvlOf(b) - lvlOf(a),
      ),
      have = MATN.map((n, i) => [i, mats()[i] || 0]).filter((x) => x[1] > 0),
      rows = own
        .map((k) => {
          const it = ITEMS[k],
            l = lvlOf(k);
          return `<div class="irow"><span class="ic eicw">${eic(it.ic)}</span><div><b style="color:${RAR[it.t].c}">${EQ[k].n}${l ? " +" + l : ""}</b>${Pl.eq[EQ[k].s] === k ? ' <span class="ok">terpasang</span>' : ""}<br><small>${RAR[it.t].n} · ${fmt(EQ[k])}</small></div><button class="b" data-up="${k}">${l >= 5 ? "MAX" : "Perkuat"}</button></div>`;
        })
        .join("");
    ui(
      `<div class="card"><b class="ok">${who}</b> <span class="qm">Penguatan equipment · Koin: ${Pl.coin}</span>` +
        `<div class="qm" style="margin:4px 0">${have.length ? have.map(([i, n]) => `${mic(i)} ${MATN[i]} ×${n}`).join(" · ") : "Kamu belum punya material. Kalahkan monster untuk mendapatkannya."}</div>` +
        `<div class="eqf">${FLT.filter((f) => f[0] !== "h")
          .map(([k, n]) => `<button class="b ${sf === k ? "" : "g"}" data-sf="${k}" type="button">${n}</button>`)
          .join("")}</div>${rows || '<div class="qm">Kamu belum punya equipment dari katalog. Dapatkan dari monster atau toko.</div>'}` +
        `<div class="row" style="margin-top:8px"><button class="b" id="smx">Tutup</button></div></div>`,
    );
    document.querySelectorAll("[data-sf]").forEach((b) => (b.onclick = () => ((sf = b.dataset.sf), smithMenu(who))));
    document.querySelectorAll("[data-up]").forEach((b) => (b.onclick = () => openUp(b.dataset.up, () => smithMenu(who))));
    document.querySelector("#smx").onclick = () => {
      busy = false;
      idle();
    };
  }
  const isSmith = (e) => e && e.t === "npc" && (/smith|pandai/i.test(e.sp || "") || /pandai/i.test((e.d && e.d[0]) || e.id || ""));
  /* bicara dengan Pandai Besi -> dialog biasa (dengan potret) lalu menu penguatan */
  let smithPend = null;
  if (typeof dlg === "function") {
    const _dlgS = dlg;
    dlg = function (who, lines, cb) {
      if (smithPend && !cb) {
        const w = smithPend;
        smithPend = null;
        return _dlgS.call(this, who, [...lines, "Mau memperkuat perlengkapanmu? Bawa material dari monster dan sedikit koin."], () => smithMenu(w));
      }
      return _dlgS.apply(this, arguments);
    };
  }
  if (typeof H !== "undefined" && typeof H.npc === "function") {
    const _hnpc = H.npc;
    H.npc = (e) => {
      if (isSmith(e) && e.d) smithPend = e.d[0];
      try {
        return _hnpc(e);
      } finally {
        smithPend = null;
      }
    };
  }

  /* ---------- toko Pedagang Kuno ---------- */
  if (typeof IT !== "undefined" && Array.isArray(IT))
    Object.keys(SHOP).forEach((k) =>
      IT.push([`${EQ[k].n} (${fmt(EQ[k])})`, EQ[k].price, () => (Pl.own[k] = 1), () => Pl.own[k]]),
    );

  /* ---------- API konsol & untuk NPC ---------- */
  const NPC_T = [0, 0, 1, 1, 2, 2, 3, 4]; /* Rank E..SSS -> tingkat equipment */
  window.EQX = {
    items: ITEMS, all: ALL, mats: MATN, rarity: RAR,
    give: (k) => {
      if (!ITEMS[k]) return false;
      Pl.own[k] = 1;
      return EQ[k].n;
    },
    mat: (i, n = 1) => ((mats()[i] = (mats()[i] || 0) + n), MATN[i]),
    text: (k) => fmt(EQ[k]),
    /* perlengkapan NPC menurut Rank (0=E ... 7=SSS) dan jenis senjata ("sword"|"archer"|"mage"): {w,b,c, stat} */
    npcGear: (rank, wt = "sword", seed = 0) => {
      const t = NPC_T[Math.max(0, Math.min(7, rank))],
        cw = CATS.find((c) => c.wt === wt) || CATS[0],
        si = (seed >>> 0) % 5,
        g = { w: cw.k + t + "_" + si, b: "ar" + t + "_" + si, c: "jb" + t + "_" + si },
        stat = {};
      Object.values(g).forEach((k) => {
        const e = EQ[k] && BASEST[k];
        if (e) for (const s in e) stat[s] = (stat[s] || 0) + e[s];
      });
      return { ...g, stat };
    },
  };
  refresh();
  console.log("[equip_katalog] aktif: " + ALL.length + " equipment, " + MATN.length + " material");
})();
